package dev.local.tvbootcleaner;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.widget.*;import android.view.*;import android.provider.Settings;import android.content.res.ColorStateList;

public class MainActivity extends Activity {
 private TextView status,shortcut,gestureButton,access;private final Handler handler=new Handler();private SharedPreferences prefs;
 private final Runnable refresh=new Runnable(){public void run(){status.setText(prefs.getString("status","Connect once, then Puff handles startup."));shortcut.setText("Remote button   ·   "+keyName(prefs.getInt("shortcut_key",0)));gestureButton.setText("Gesture   ·   "+(prefs.getBoolean("shortcut_long",false)?"Long-press":"Double-press"));String enabled=Settings.Secure.getString(getContentResolver(),Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES);access.setText(enabled!=null&&enabled.contains("dev.local.tvbootcleaner/")?"Home controls   ·   Enabled":"Enable Home controls");handler.postDelayed(this,1500);}};
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("config",0);
  if(!getPackageManager().hasSystemFeature("android.software.leanback")){startActivity(new Intent(this,io.github.jqssun.airplay.MainActivity.class));finish();return;}
  LinearLayout root=new LinearLayout(this);root.setPadding(d(52),d(32),d(52),d(32));root.setBackground(PuffStyle.night());setContentView(root);
  LinearLayout hero=new LinearLayout(this);hero.setOrientation(1);hero.setPadding(0,d(14),d(44),0);root.addView(hero,new LinearLayout.LayoutParams(0,-1,1));
  PuffStyle.Cloud cloud=new PuffStyle.Cloud(this);hero.addView(cloud,new LinearLayout.LayoutParams(d(112),d(112)));
  hero.addView(PuffStyle.text(this,"Puff",46,PuffStyle.WHITE));TextView tag=PuffStyle.text(this,"A little space to breathe.",20,PuffStyle.MUTED);tag.setPadding(0,d(6),0,d(18));hero.addView(tag);
  LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(d(20),d(18),d(20),d(18));card.setBackground(PuffStyle.glass(d(24)));card.addView(PuffStyle.text(this,"LAST CLEANUP",12,PuffStyle.MINT));status=PuffStyle.text(this,"",18,PuffStyle.WHITE);status.setPadding(0,d(12),0,0);card.addView(status);hero.addView(card);
  TextView note=PuffStyle.text(this,"Your apps and sign-ins stay.\nPuff appears only on Home, never inside a streaming app.",15,PuffStyle.MUTED);note.setPadding(0,d(24),0,0);hero.addView(note);
  ScrollView scroll=new ScrollView(this);scroll.setClipToPadding(false);root.addView(scroll,new LinearLayout.LayoutParams(0,-1,1.35f));LinearLayout controls=new LinearLayout(this);controls.setOrientation(1);controls.setPadding(d(8),d(8),d(8),d(20));scroll.addView(controls);
  controls.addView(PuffStyle.text(this,"Make yourself at Home",26,PuffStyle.WHITE));
  controls.addView(PuffStyle.button(this,"Cast · iPhone & Android",()->startActivity(new Intent(this,io.github.jqssun.airplay.MainActivity.class))),PuffStyle.row(this));
  toggle(controls,"Clean automatically after restart","enabled",false);toggle(controls,"Floating control on Home","overlay_enabled",true);
  access=PuffStyle.button(this,"Enable Home controls",()->openAccessibility());controls.addView(access,PuffStyle.row(this));
  shortcut=PuffStyle.button(this,"Remote button",()->chooseKey());controls.addView(shortcut,PuffStyle.row(this));
  gestureButton=PuffStyle.button(this,"Gesture",()->new AlertDialog.Builder(this).setTitle("Open Puff with…").setSingleChoiceItems(new String[]{"Double-press (within ½ second)","Long-press (hold, then release)"},prefs.getBoolean("shortcut_long",false)?1:0,(dialog,which)->{prefs.edit().putBoolean("shortcut_long",which==1).apply();dialog.dismiss();refreshNow();}).setNegativeButton("Cancel",null).show());controls.addView(gestureButton,PuffStyle.row(this));
  TextView hint=PuffStyle.text(this,"The selected button is reserved for Puff only on Home. Power, Home, Back, volume and navigation buttons are kept free.",13,PuffStyle.MUTED);hint.setPadding(d(8),d(12),d(8),d(4));controls.addView(hint);
  controls.addView(PuffStyle.button(this,"Preview on Home",()->{prefs.edit().putBoolean("preview_overlay",true).apply();startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}),PuffStyle.row(this));
  controls.addView(PuffStyle.button(this,"Clean apps now",()->start("manual")),PuffStyle.row(this));
  controls.addView(PuffStyle.button(this,"Authorize this TV",()->start("authorize")),PuffStyle.row(this));
  TextView footer=PuffStyle.text(this,"Home controls use accessibility to check the foreground app and your chosen remote button. No screen text or key history is saved. Keep USB debugging on for cleanup.\n\nPuff 3.0 beta · Cleanup + casting\nFree software · GPLv3. Includes UxPlay, Android AirPlay Server, AirPlay/DLNA Receiver and AdbLib.",13,PuffStyle.MUTED);footer.setPadding(d(8),d(20),d(8),0);controls.addView(footer);access.requestFocus();
 }
 private void openAccessibility(){new AlertDialog.Builder(this).setTitle("Puff Home controls").setMessage("On this OnePlus TV, go to:\n\nDevice Preferences → Accessibility → Puff Home controls → Enable\n\nPuff checks window package names and your chosen remote button. It does not save screen text or keystroke history.").setPositiveButton("Open TV Settings",(a,b)->startActivity(new Intent(Settings.ACTION_SETTINGS))).setNegativeButton("Cancel",null).show();}
 private int d(float n){return PuffStyle.d(this,n);}
 private void toggle(LinearLayout parent,String label,String key,boolean defaultValue){Switch sw=new Switch(this);sw.setText(label);sw.setTextColor(PuffStyle.WHITE);sw.setTextSize(18);sw.setPadding(d(16),d(14),d(16),d(14));sw.setBackground(PuffStyle.glass(d(18)));sw.setThumbTintList(ColorStateList.valueOf(PuffStyle.MINT));sw.setTrackTintList(ColorStateList.valueOf(0xff444444));sw.setChecked(prefs.getBoolean(key,defaultValue));sw.setOnCheckedChangeListener((v,on)->{prefs.edit().putBoolean(key,on).apply();if(key.equals("enabled")&&!on)stopService(new Intent(this,CleanupService.class));});sw.setOnFocusChangeListener((v,on)->{v.setBackground(on?PuffStyle.solid(0xff292929,d(18)):PuffStyle.glass(d(18)));});parent.addView(sw,PuffStyle.row(this));}
 static String keyName(int key){if(key==0)return "Not assigned";String s=KeyEvent.keyCodeToString(key).replace("KEYCODE_","").replace("PROG_","").replace('_',' ');return s.substring(0,1)+s.substring(1).toLowerCase(java.util.Locale.ROOT);}
 static String shortcutLabel(SharedPreferences p){int k=p.getInt("shortcut_key",0);return k==0?"Home companion":(p.getBoolean("shortcut_long",false)?"Hold ":"Double ")+keyName(k);}
 private boolean allowed(int k){switch(k){case KeyEvent.KEYCODE_UNKNOWN:case KeyEvent.KEYCODE_HOME:case KeyEvent.KEYCODE_POWER:case KeyEvent.KEYCODE_BACK:case KeyEvent.KEYCODE_DPAD_UP:case KeyEvent.KEYCODE_DPAD_DOWN:case KeyEvent.KEYCODE_DPAD_LEFT:case KeyEvent.KEYCODE_DPAD_RIGHT:case KeyEvent.KEYCODE_DPAD_CENTER:case KeyEvent.KEYCODE_ENTER:case KeyEvent.KEYCODE_VOLUME_UP:case KeyEvent.KEYCODE_VOLUME_DOWN:case KeyEvent.KEYCODE_VOLUME_MUTE:case KeyEvent.KEYCODE_MUTE:case KeyEvent.KEYCODE_ASSIST:case KeyEvent.KEYCODE_VOICE_ASSIST:case KeyEvent.KEYCODE_SLEEP:case KeyEvent.KEYCODE_WAKEUP:return false;default:return true;}}
 private void chooseKey(){
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Choose a remote button").setMessage("Press the spare button you want to use.\n\nColoured keys or Menu usually work well. Some TV-reserved buttons cannot be detected. Back cancels.").setNegativeButton("Cancel",null).setNeutralButton("Clear shortcut",(a,b)->{prefs.edit().putInt("shortcut_key",0).apply();refreshNow();}).create();
  dialog.setOnKeyListener((a,key,event)->{if(key==KeyEvent.KEYCODE_BACK||key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER||key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT||key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN)return false;if(!allowed(key))return false;if(event.getAction()==KeyEvent.ACTION_UP){prefs.edit().putInt("shortcut_key",key).apply();dialog.dismiss();refreshNow();}return true;});dialog.show();
 }
 private void refreshNow(){handler.removeCallbacks(refresh);if(status!=null)handler.post(refresh);}
 private void start(String action){prefs.edit().putString("status","Connecting locally…").apply();startForegroundService(new Intent(this,CleanupService.class).setAction(action));}
 public void onResume(){super.onResume();refreshNow();}public void onPause(){super.onPause();handler.removeCallbacks(refresh);}
}
